/**
 * @title VulnerableVault
 * @notice Demonstrates reentrancy vulnerability (Checks-Effects-Interactions pattern violation)
 * @dev DO NOT USE IN PRODUCTION - Intentionally vulnerable for testing
 */
contract VulnerableVault {
    mapping(address => uint256) public balances;

    event Deposit(address indexed user, uint256 amount);
    event Withdrawal(address indexed user, uint256 amount);

    function deposit() external payable {
        require(msg.value > 0, "Must send ETH");
        balances[msg.sender] += msg.value;
        emit Deposit(msg.sender, msg.value);
    }

    /**
     * @notice Vulnerable withdraw function - external call before state update
     */
    function withdraw() external {
        uint256 bal = balances[msg.sender];
        require(bal > 0, "Insufficient balance");

        // VULNERABILITY: External call before state update
        (bool success, ) = msg.sender.call{value: bal}("");
        require(success, "Transfer failed");

        // State update happens after external call (should be before)
        balances[msg.sender] = 0;

        emit Withdrawal(msg.sender, bal);
    }

    function getBalance() external view returns (uint256) {
        return address(this).balance;
    }
}

/**
 * @title AccessControlVulnerable
 * @notice Missing access control on critical functions
 * @dev Demonstrates missing authorization checks
 */
contract AccessControlVulnerable {
    address public owner;
    uint256 public sensitiveValue;
    mapping(address => uint256) private userData;

    event OwnershipChanged(address indexed previousOwner, address indexed newOwner);

    constructor() {
        owner = msg.sender;
    }

    /**
     * @notice VULNERABILITY: No access control - anyone can change owner
     */
    function changeOwner(address newOwner) external {
        // Missing: require(msg.sender == owner, "Not authorized");
        address previousOwner = owner;
        owner = newOwner;
        emit OwnershipChanged(previousOwner, newOwner);
    }

    /**
     * @notice VULNERABILITY: No access control on sensitive operation
     */
    function updateSensitiveValue(uint256 newValue) external {
        // No authorization check
        sensitiveValue = newValue;
    }

    function updateUserData(address user, uint256 data) external {
        // No access control
        userData[user] = data;
    }
}

/**
 * @title IntegerOverflowTest
 * @notice Demonstrates integer overflow/underflow scenarios
 * @dev Using unchecked blocks to simulate pre-0.8 behavior for audit testing
 */
contract IntegerOverflowTest {
    uint8 public smallNumber = 255;
    uint256 public balance = type(uint256).max;
    uint256 public counter;

    function incrementOverflow() external {
        unchecked {
            smallNumber += 1; // Will overflow to 0
        }
    }

    function addToBalance(uint256 amount) external {
        unchecked {
            balance += amount; // Potential overflow
        }
    }

    function subtractBalance(uint256 amount) external {
        unchecked {
            balance -= amount; // Potential underflow if amount > balance
        }
    }

    function decrementCounter() external {
        unchecked {
            counter -= 1; // Underflow if counter is 0
        }
    }
}

/**
 * @title UncheckedExternalCall
 * @notice Demonstrates unchecked low-level calls and delegatecall vulnerabilities
 */
contract UncheckedExternalCall {
    address public implementation;

    constructor(address _implementation) {
        implementation = _implementation;
    }

    /**
     * @notice VULNERABILITY: Unchecked call return value
     */
    function sendEther(address payable recipient, uint256 amount) external {
        // Not checking return value - funds might not be sent but no revert
        recipient.call{value: amount}("");
    }

    /**
     * @notice VULNERABILITY: Unchecked delegatecall
     */
    function upgradeLogic(address newImplementation) external {
        // No validation on newImplementation
        implementation = newImplementation;
    }

    fallback() external payable {
        (bool success, ) = implementation.delegatecall(msg.data);
        // Not checking success
    }
}

/**
 * @title TimestampDependence
 * @notice Vulnerable to timestamp manipulation by miners
 */
contract TimestampDependence {
    uint256 public lastPayoutTime;
    mapping(address => uint256) public payouts;

    /**
     * @notice VULNERABILITY: Strict equality with timestamp
     */
    function isExactTime(uint256 targetTime) external view returns (bool) {
        return block.timestamp == targetTime;
    }

    /**
     * @notice VULNERABILITY: Predictable randomness using block data
     */
    function randomNumber() external view returns (uint256) {
        return uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty, msg.sender)));
    }

    /**
     * @notice VULNERABILITY: Time-based logic without buffer
     */
    function claimPayout() external {
        require(block.timestamp > lastPayoutTime + 1 days, "Too early");
        // Miner can manipulate timestamp slightly to affect this
        payouts[msg.sender] += 1 ether;
        lastPayoutTime = block.timestamp;
    }
}

/**
 * @title UnprotectedSelfDestruct
 * @notice Contract vulnerable to forced ether sending and destruction
 */
contract UnprotectedSelfDestruct {
    address public owner;
    uint256 public balance;

    constructor() payable {
        owner = msg.sender;
        balance = msg.value;
    }

    /**
     * @notice VULNERABILITY: Anyone can destroy contract
     */
    function destroy() external {
        // Missing access control
        selfdestruct(payable(msg.sender));
    }

    /**
     * @notice VULNERABILITY: No way to withdraw except selfdestruct
     */
    receive() external payable {
        balance += msg.value;
    }
}

