// SECURE CONTRACTS (Reference Implementations)
// ============================================

/**
 * @title SecureVault
 * @notice Reentrancy-protected vault with proper CEI pattern
 */
contract SecureVault {
    using Address for address;

    mapping(address => uint256) private balances;
    bool private locked;

    event Deposit(address indexed user, uint256 amount);
    event Withdrawal(address indexed user, uint256 amount);

    modifier nonReentrant() {
        require(!locked, "Reentrant call detected");
        locked = true;
        _;
        locked = false;
    }

    function deposit() external payable {
        require(msg.value > 0, "Must send ETH");
        balances[msg.sender] += msg.value;
        emit Deposit(msg.sender, msg.value);
    }

    /**
     * @notice Secure withdraw following Checks-Effects-Interactions
     */
    function withdraw() external nonReentrant {
        uint256 bal = balances[msg.sender];
        require(bal > 0, "Insufficient balance");

        // Effects: Update state before interaction
        balances[msg.sender] = 0;

        // Interaction: External call last
        (bool success, ) = msg.sender.call{value: bal}("");
        require(success, "Transfer failed");

        emit Withdrawal(msg.sender, bal);
    }

    function balanceOf(address user) external view returns (uint256) {
        return balances[user];
    }

    function getContractBalance() external view returns (uint256) {
        return address(this).balance;
    }
}

/**
 * @title AccessControlled
 * @notice Proper access control implementation using OpenZeppelin patterns
 */
contract AccessControlled {
    address private _owner;
    mapping(address => bool) private _operators;
    mapping(bytes4 => bool) private _pausedFunctions;
    bool private _paused;

    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event OperatorAdded(address indexed operator);
    event OperatorRemoved(address indexed operator);
    event FunctionPaused(bytes4 indexed functionSelector);
    event FunctionUnpaused(bytes4 indexed functionSelector);

    modifier onlyOwner() {
        require(msg.sender == _owner, "Caller is not owner");
        _;
    }

    modifier onlyOperator() {
        require(_operators[msg.sender] || msg.sender == _owner, "Not authorized");
        _;
    }

    modifier whenNotPaused() {
        require(!_paused, "Contract is paused");
        _;
    }

    modifier whenNotPausedFunction(bytes4 selector) {
        require(!_pausedFunctions[selector], "Function is paused");
        _;
    }

    constructor() {
        _owner = msg.sender;
        _operators[msg.sender] = true;
        emit OwnershipTransferred(address(0), msg.sender);
    }

    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "Invalid address");
        require(newOwner != _owner, "New owner is current owner");
        address oldOwner = _owner;
        _owner = newOwner;
        emit OwnershipTransferred(oldOwner, newOwner);
    }

    function addOperator(address operator) external onlyOwner {
        require(operator != address(0), "Invalid address");
        require(!_operators[operator], "Already operator");
        _operators[operator] = true;
        emit OperatorAdded(operator);
    }

    function removeOperator(address operator) external onlyOwner {
        require(_operators[operator], "Not an operator");
        _operators[operator] = false;
        emit OperatorRemoved(operator);
    }

    function pause() external onlyOwner {
        _paused = true;
    }

    function unpause() external onlyOwner {
        _paused = false;
    }

    function pauseFunction(bytes4 selector) external onlyOwner {
        _pausedFunctions[selector] = true;
        emit FunctionPaused(selector);
    }

    function isOperator(address account) external view returns (bool) {
        return _operators[account] || account == _owner;
    }

    function owner() external view returns (address) {
        return _owner;
    }
}

/**
 * @title SafeERC20Handler
 * @notice Secure token handling with proper error checking
 */
contract SafeERC20Handler {
    using SafeERC20 for IERC20;

    mapping(address => mapping(address => uint256)) public deposits;

    event Deposit(address indexed token, address indexed user, uint256 amount);
    event Withdrawal(address indexed token, address indexed user, uint256 amount);

    function depositERC20(address token, uint256 amount) external {
        require(token != address(0), "Invalid token");
        require(amount > 0, "Amount must be > 0");

        uint256 balanceBefore = IERC20(token).balanceOf(address(this));

        // Safe transfer with revert on failure
        SafeERC20.safeTransferFrom(IERC20(token), msg.sender, address(this), amount);

        uint256 balanceAfter = IERC20(token).balanceOf(address(this));
        uint256 actualReceived = balanceAfter - balanceBefore;

        require(actualReceived == amount, "Transfer fee detected or transfer failed");

        deposits[token][msg.sender] += actualReceived;
        emit Deposit(token, msg.sender, actualReceived);
    }

    function withdrawERC20(address token, uint256 amount) external {
        require(deposits[token][msg.sender] >= amount, "Insufficient balance");

        deposits[token][msg.sender] -= amount;

        SafeERC20.safeTransfer(IERC20(token), msg.sender, amount);
        emit Withdrawal(token, msg.sender, amount);
    }
}

// ============================================
// UTILITY LIBRARIES
// ============================================

library SafeERC20 {
    function safeTransfer(IERC20 token, address to, uint256 value) internal {
        require(address(token).code.length > 0, "SafeERC20: call to non-contract");
        (bool success, bytes memory returndata) = address(token).call(
            abi.encodeWithSelector(IERC20.transfer.selector, to, value)
        );
        require(success && (returndata.length == 0 || abi.decode(returndata, (bool))), "SafeERC20: transfer failed");
    }

    function safeTransferFrom(IERC20 token, address from, address to, uint256 value) internal {
        require(address(token).code.length > 0, "SafeERC20: call to non-contract");
        (bool success, bytes memory returndata) = address(token).call(
            abi.encodeWithSelector(IERC20.transferFrom.selector, from, to, value)
        );
        require(success && (returndata.length == 0 || abi.decode(returndata, (bool))), "SafeERC20: transferFrom failed");
    }
}

library Address {
    function isContract(address account) internal view returns (bool) {
        return account.code.length > 0;
    }

    function sendValue(address payable recipient, uint256 amount) internal {
        require(address(this).balance >= amount, "Address: insufficient balance");
        (bool success, ) = recipient.call{value: amount}("");
        require(success, "Address: unable to send value");
    }
}

interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
}

