/**
 * @title FlashLoanMock
 * @notice Mock flash loan provider for testing reentrancy in DeFi contexts
 */
contract FlashLoanMock {
    using SafeERC20 for IERC20;

    IERC20 public token;
    uint256 public fee = 9; // 0.09% fee (9 basis points)

    event FlashLoan(address indexed receiver, uint256 amount, uint256 fee);

    constructor(address _token) {
        token = IERC20(_token);
    }

    function flashLoan(uint256 amount) external {
        uint256 balanceBefore = token.balanceOf(address(this));
        require(balanceBefore >= amount, "Insufficient liquidity");

        uint256 feeAmount = (amount * fee) / 10000;

        // Transfer to receiver
        SafeERC20.safeTransfer(token, msg.sender, amount);

        // Execute callback
        IFlashLoanReceiver(msg.sender).executeOperation(amount, feeAmount, address(token));

        // Verify repayment
        uint256 balanceAfter = token.balanceOf(address(this));
        require(balanceAfter >= balanceBefore + feeAmount, "Flash loan not repaid");

        emit FlashLoan(msg.sender, amount, feeAmount);
    }
}

interface IFlashLoanReceiver {
    function executeOperation(uint256 amount, uint256 fee, address token) external;
}

/**
 * @title UpgradeableProxy
 * @notice Secure proxy pattern implementation
 */
contract UpgradeableProxy {
    bytes32 private constant IMPLEMENTATION_SLOT = keccak256("audit.proxy.implementation");
    bytes32 private constant ADMIN_SLOT = keccak256("audit.proxy.admin");

    modifier ifAdmin() {
        require(msg.sender == _admin(), "Not admin");
        _;
    }

    constructor(address _implementation) {
        _setImplementation(_implementation);
        _setAdmin(msg.sender);
    }

    function upgradeTo(address newImplementation) external ifAdmin {
        require(newImplementation != address(0), "Invalid address");
        require(newImplementation.code.length > 0, "Not a contract");
        _setImplementation(newImplementation);
    }

    function _delegate(address impl) internal {
        assembly {
            calldatacopy(0, 0, calldatasize())
            let result := delegatecall(gas(), impl, 0, calldatasize(), 0, 0)
            returndatacopy(0, 0, returndatasize())
            switch result
            case 0 { revert(0, returndatasize()) }
            default { return(0, returndatasize()) }
        }
    }

    fallback() external payable {
        _delegate(_implementation());
    }

    receive() external payable {}

    function _implementation() internal view returns (address impl) {
        bytes32 slot = IMPLEMENTATION_SLOT;
        assembly {
            impl := sload(slot)
        }
    }

    function _admin() internal view returns (address adm) {
        bytes32 slot = ADMIN_SLOT;
        assembly {
            adm := sload(slot)
        }
    }

    function _setImplementation(address newImplementation) internal {
        bytes32 slot = IMPLEMENTATION_SLOT;
        assembly {
            sstore(slot, newImplementation)
        }
    }

    function _setAdmin(address newAdmin) internal {
        bytes32 slot = ADMIN_SLOT;
        assembly {
            sstore(slot, newAdmin)
        }
    }
}

