pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title LendingCore
 * @notice Core lending protocol for DeFi-Lend
 * @dev Handles deposits, borrows, liquidations, and flash loans
 * @author DeFi-Lend Team
 */
contract LendingCore is Ownable, ReentrancyGuard {
    // ============ State Variables ============

    mapping(address => uint256) public deposits;
    mapping(address => uint256) public borrows;
    mapping(address => uint256) public lastUpdateTime;

    uint256 public totalDeposits;
    uint256 public totalBorrows;
    uint256 public interestRate = 5; // 5% APY basis points handling done in calc
    uint256 public collateralFactor = 75; // 75% LTV ratio
    uint256 public liquidationBonus = 105; // 5% bonus to liquidators

    IERC20 public immutable token;

    // ============ Events ============

    event Deposit(address indexed user, uint256 amount, uint256 timestamp);
    event Withdraw(address indexed user, uint256 amount);
    event Borrow(address indexed user, uint256 amount, uint256 collateral);
    event Repay(address indexed user, uint256 amount, uint256 remainingDebt);
    event Liquidate(address indexed borrower, address indexed liquidator, uint256 debtAmount, uint256 collateralSeized);
    event FlashLoan(address indexed receiver, uint256 amount, uint256 fee, bool success);
    event InterestRateUpdated(uint256 oldRate, uint256 newRate);

    // ============ Modifiers ============

    modifier hasDeposit(uint256 amount) {
        require(deposits[msg.sender] >= amount, "Insufficient deposit balance");
        _;
    }

    modifier validAmount(uint256 amount) {
        require(amount > 0, "Amount must be greater than zero");
        _;
    }

    // ============ Constructor ============

    constructor(address _token) Ownable(msg.sender) {
        require(_token != address(0), "Invalid token address");
        token = IERC20(_token);
    }

    // ============ Core Lending Functions ============

    /**
     * @notice Deposit tokens into the lending pool
     * @param amount Amount of tokens to deposit
     */
    function deposit(uint256 amount) external validAmount(amount) {
        require(token.transferFrom(msg.sender, address(this), amount), "Transfer failed");

        deposits[msg.sender] += amount;
        totalDeposits += amount;
        lastUpdateTime[msg.sender] = block.timestamp;

        emit Deposit(msg.sender, amount, block.timestamp);
    }

    /**
     * @notice Withdraw deposited tokens
     * @param amount Amount to withdraw
     * @dev VULNERABILITY: External call before state update (lines 145-152)
     */
    function withdraw(uint256 amount) external validAmount(amount) hasDeposit(amount) {
        // CRITICAL: External call happens before state update
        // This violates Checks-Effects-Interactions pattern
        require(token.transfer(msg.sender, amount), "Transfer failed");

        // State updates happen after external call - reentrancy risk
        deposits[msg.sender] -= amount;
        totalDeposits -= amount;

        emit Withdraw(msg.sender, amount);
    }

    /**
     * @notice Borrow tokens against deposited collateral
     * @param amount Amount to borrow
     */
    function borrow(uint256 amount) external validAmount(amount) {
        uint256 userDeposits = deposits[msg.sender];
        uint256 maxBorrow = (userDeposits * collateralFactor) / 100;
        uint256 currentBorrow = borrows[msg.sender];

        require(currentBorrow + amount <= maxBorrow, "Insufficient collateral");

        borrows[msg.sender] = currentBorrow + amount;
        totalBorrows += amount;
        lastUpdateTime[msg.sender] = block.timestamp;

        require(token.transfer(msg.sender, amount), "Borrow transfer failed");

        emit Borrow(msg.sender, amount, userDeposits);
    }

    /**
     * @notice Repay borrowed tokens
     * @param amount Amount to repay
     */
    function repay(uint256 amount) external validAmount(amount) {
        uint256 currentBorrow = borrows[msg.sender];
        require(currentBorrow >= amount, "Repay amount exceeds debt");

        require(token.transferFrom(msg.sender, address(this), amount), "Repay transfer failed");

        uint256 newBorrow = currentBorrow - amount;
        borrows[msg.sender] = newBorrow;
        totalBorrows -= amount;

        emit Repay(msg.sender, amount, newBorrow);
    }

    /**
     * @notice Liquidate an undercollateralized position
     * @param borrower Address of borrower to liquidate
     * @param debtAmount Amount of debt to repay
     */
    function liquidate(address borrower, uint256 debtAmount) external validAmount(debtAmount) {
        uint256 borrowerDebt = borrows[borrower];
        uint256 borrowerDeposits = deposits[borrower];

        require(borrowerDebt > 0, "No debt to liquidate");
        require(debtAmount <= borrowerDebt, "Debt amount too high");

        // Check if position is undercollateralized
        uint256 maxAllowedBorrow = (borrowerDeposits * collateralFactor) / 100;
        require(borrowerDebt > maxAllowedBorrow, "Position not liquidatable");

        // Transfer debt repayment from liquidator
        require(token.transferFrom(msg.sender, address(this), debtAmount), "Liquidation payment failed");

        // Calculate collateral to seize (debt + 5% bonus)
        uint256 collateralToSeize = (debtAmount * liquidationBonus) / 100;
        require(collateralToSeize <= borrowerDeposits, "Collateral seize amount too high");

        // Update state
        borrows[borrower] = borrowerDebt - debtAmount;
        totalBorrows -= debtAmount;
        deposits[borrower] = borrowerDeposits - collateralToSeize;
        deposits[msg.sender] += collateralToSeize;

        emit Liquidate(borrower, msg.sender, debtAmount, collateralToSeize);
    }

    /**
     * @notice Execute flash loan
     * @param receiver Contract to receive flash loan
     * @param amount Amount to loan
     * @param data Calldata for receiver
     * @dev VULNERABILITY: Line 198 - external call without reentrancy protection
     */
    function flashLoan(address receiver, uint256 amount, bytes calldata data) external validAmount(amount) {
        require(amount <= totalDeposits, "Insufficient liquidity for flash loan");

        uint256 fee = (amount * 9) / 10000; // 0.09% fee
        uint256 balanceBefore = token.balanceOf(address(this));

        // Transfer tokens to receiver
        require(token.transfer(receiver, amount), "Flash loan transfer failed");

        // CRITICAL: External call to untrusted contract (line 198)
        // Missing nonReentrant modifier despite inheriting ReentrancyGuard
        (bool success, ) = receiver.call(data);
        require(success, "Flash loan execution failed");

        // Verify repayment
        uint256 balanceAfter = token.balanceOf(address(this));
        require(balanceAfter >= balanceBefore + fee, "Flash loan not repaid with fee");

        emit FlashLoan(receiver, amount, fee, success);
    }

    // ============ View Functions ============

    /**
     * @notice Calculate accrued interest for a user
     * @param user Address to calculate for
     * @return interest Accrued interest amount
     * @dev GAS ISSUE: Line 234 - storage variable read in loop
     */
    function calculateInterest(address user) public view returns (uint256) {
        uint256 principal = borrows[user];
        if (principal == 0) return 0;

        uint256 timeDiff = block.timestamp - lastUpdateTime[user];
        if (timeDiff == 0) return 0;

        // GAS INEFFICIENT: Reading storage variable 'interestRate' in every iteration
        // Should cache in memory before loop
        uint256 accumulatedInterest = 0;
        for (uint256 i = 0; i < timeDiff; i++) {
            // Line 234: SLOAD operation in loop - very expensive
            accumulatedInterest += (principal * interestRate) / (100 * 365 days);
        }

        return accumulatedInterest;
    }

    /**
     * @notice Get account health factor
     * @param user Address to check
     * @return health Health factor (100 = perfectly collateralized at threshold)
     */
    function getHealthFactor(address user) external view returns (uint256) {
        uint256 depositValue = deposits[user];
        uint256 borrowValue = borrows[user];

        if (borrowValue == 0) return type(uint256).max;

        uint256 collateralValue = (depositValue * collateralFactor) / 100;
        return (collateralValue * 100) / borrowValue;
    }

    // ============ Admin Functions ============

    /**
     * @notice Update interest rate (admin only)
     * @param newRate New annual interest rate in percentage
     */
    function updateInterestRate(uint256 newRate) external onlyOwner {
        require(newRate <= 100, "Rate too high");
        uint256 oldRate = interestRate;
        interestRate = newRate;
        emit InterestRateUpdated(oldRate, newRate);
    }

    /**
     * @notice Emergency token recovery (for stuck tokens)
     * @param tokenAddress Token to recover
     * @param amount Amount to recover
     */
    function recoverToken(address tokenAddress, uint256 amount) external onlyOwner {
        require(tokenAddress != address(token), "Cannot recover lending token");
        IERC20(tokenAddress).transfer(owner(), amount);
    }
}

require('dotenv').config();

const express = require('express');
const cors = require('cors');
const helmet = require('helmet');
const morgan = require('morgan');
const jwt = require('jsonwebtoken');
const bcrypt = require('bcryptjs');
const { body, validationResult } = require('express-validator');
const { RateLimiterMemory } = require('rate-limiter-flexible');

const app = express();
const PORT = process.env.PORT || 3000;
const JWT_SECRET = process.env.JWT_SECRET || 'your-secret-key-change-in-production';
const NODE_ENV = process.env.NODE_ENV || 'development';

// Rate limiter configuration
const rateLimiter = new RateLimiterMemory({
  keyPrefix: 'auth_limit',
  points: 5,
  duration: 60,
});

// Middleware
app.use(helmet());
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true
}));
app.use(express.json());
app.use(morgan(NODE_ENV === 'production' ? 'combined' : 'dev'));

// In-memory user store (replace with database in production)
const users = new Map();

// Rate limiting middleware
const rateLimitMiddleware = async (req, res, next) => {
  try {
    await rateLimiter.consume(req.ip);
    next();
  } catch {
    res.status(429).json({ 
      error: 'Too many requests', 
      message: 'Please try again later' 
    });
  }
};

// Health check endpoint
app.get('/health', (req, res) => {
  res.status(200).json({
    status: 'healthy',
    service: 'auth-service',
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// Registration endpoint
app.post('/api/auth/register',
  rateLimitMiddleware,
  [
    body('email').isEmail().normalizeEmail(),
    body('password').isLength({ min: 8 }).withMessage('Password must be at least 8 characters'),
    body('username').trim().isLength({ min: 3, max: 30 })
  ],
  async (req, res) => {
    try {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ errors: errors.array() });
      }

      const { email, password, username } = req.body;

      if (users.has(email)) {
        return res.status(409).json({ error: 'User already exists' });
      }

      const hashedPassword = await bcrypt.hash(password, 12);
      const userId = `user_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

      users.set(email, {
        id: userId,
        email,
        username,
        password: hashedPassword,
        createdAt: new Date().toISOString()
      });

      const token = jwt.sign(
        { userId, email, username },
        JWT_SECRET,
        { expiresIn: '24h', issuer: 'auth-service' }
      );

      res.status(201).json({
        message: 'User registered successfully',
        token,
        user: { id: userId, email, username }
      });
    } catch (error) {
      console.error('Registration error:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// Login endpoint
app.post('/api/auth/login',
  rateLimitMiddleware,
  [
    body('email').isEmail().normalizeEmail(),
    body('password').exists()
  ],
  async (req, res) => {
    try {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ errors: errors.array() });
      }

      const { email, password } = req.body;
      const user = users.get(email);

      if (!user) {
        return res.status(401).json({ error: 'Invalid credentials' });
      }

      const isValidPassword = await bcrypt.compare(password, user.password);
      if (!isValidPassword) {
        return res.status(401).json({ error: 'Invalid credentials' });
      }

      const token = jwt.sign(
        { userId: user.id, email: user.email, username: user.username },
        JWT_SECRET,
        { expiresIn: '24h', issuer: 'auth-service' }
      );

      res.json({
        message: 'Login successful',
        token,
        user: {
          id: user.id,
          email: user.email,
          username: user.username
        }
      });
    } catch (error) {
      console.error('Login error:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// Token verification endpoint
app.post('/api/auth/verify', (req, res) => {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'No token provided' });
  }

  const token = authHeader.substring(7);

  try {
    const decoded = jwt.verify(token, JWT_SECRET);
    res.json({
      valid: true,
      user: {
        userId: decoded.userId,
        email: decoded.email,
        username: decoded.username
      }
    });
  } catch (error) {
    res.status(401).json({ 
      valid: false, 
      error: 'Invalid or expired token' 
    });
  }
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  res.status(500).json({ 
    error: 'Internal server error',
    message: NODE_ENV === 'development' ? err.message : 'Something went wrong'
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Endpoint not found' });
});

// Start server
app.listen(PORT, () => {
  console.log(`Auth service running on port ${PORT} in ${NODE_ENV} mode`);
  console.log(`Health check available at http://localhost:${PORT}/health`);
});

module.exports = app;

