#!/usr/bin/env python3
"""
Smart Home Media Library Synchronization Tool
Synchronizes local MP3/FLAC files with various IoT smart speakers.
Supports Sonos, Amazon Echo, and Google Nest devices.
"""

import os
import json
import hashlib
import argparse
import logging
import requests
import xml.etree.ElementTree as ET
from pathlib import Path
from datetime import datetime, timezone
from typing import Dict, List, Optional, Tuple
from abc import ABC, abstractmethod
from dataclasses import dataclass, field

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(name)s - %(levelname)s - %(message)s',
    handlers=[
        logging.StreamHandler(),
        logging.FileHandler('/var/log/media_sync.log')
    ]
)
logger = logging.getLogger('MediaSync')


@dataclass
class MediaFile:
    """Represents a media file in the local library."""
    path: Path
    checksum: str
    size: int
    modified_time: datetime
    format: str
    metadata: Dict = field(default_factory=dict)


class SpeakerClient(ABC):
    """Abstract base class for speaker API clients."""

    def __init__(self, config: Dict):
        self.config = config
        self.device_id = config['id']
        self.ip_address = config['ip_address']
        self.api_port = config['api_port']
        self.session = requests.Session()
        self.session.timeout = 30

    @abstractmethod
    def get_remote_inventory(self) -> Dict[str, str]:
        """Retrieve current media inventory from the speaker."""
        pass

    @abstractmethod
    def upload_file(self, media_file: MediaFile) -> bool:
        """Upload a file to the speaker."""
        pass

    @abstractmethod
    def delete_file(self, remote_id: str) -> bool:
        """Delete a file from the speaker."""
        pass

    @abstractmethod
    def update_playlist(self, file_ids: List[str]) -> bool:
        """Update the master playlist on the speaker."""
        pass


class SonosClient(SpeakerClient):
    """Client for Sonos speakers using SOAP/UPnP APIs."""

    def __init__(self, config: Dict):
        super().__init__(config)
        self.base_url = f"http://{self.ip_address}:{self.api_port}"
        self.control_url = f"{self.base_url}/MediaServer/ContentDirectory/Control"

    def _send_soap(self, action: str, body: str) -> Optional[ET.Element]:
        """Send SOAP request to Sonos device."""
        soap envelope = f"""<?xml version="1.0" encoding="utf-8"?>
        <s:Envelope xmlns:s="http://schemas.xmlsoap.org/soap/envelope/" s:encodingStyle="http://schemas.xmlsoap.org/soap/encoding/">
            <s:Body>
                <u:{action} xmlns:u="urn:schemas-upnp-org:service:ContentDirectory:1">
                    {body}
                </u:{action}>
            </s:Body>
        </s:Envelope>"""

        headers = {
            'Content-Type': 'text/xml; charset=utf-8',
            'SOAPAction': f'"urn:schemas-upnp-org:service:ContentDirectory:1#{action}"'
        }

        try:
            response = self.session.post(self.control_url, data=soap envelope, headers=headers)
            response.raise_for_status()
            return ET.fromstring(response.content)
        except Exception as e:
            logger.error(f"SOAP error for {self.device_id}: {e}")
            return None

    def get_remote_inventory(self) -> Dict[str, str]:
        """Retrieve current track list from Sonos."""
        inventory = {}
        result = self._send_soap("Browse", 
            '<ObjectID>Q:0</ObjectID><BrowseFlag>BrowseDirectChildren</BrowseFlag><Filter>*</Filter><StartingIndex>0</StartingIndex><RequestedCount>100</RequestedCount><SortCriteria></SortCriteria>')

        if result is not None:
            # Parse DIDL-Lite content for track IDs and URIs
            for item in result.iter('{urn:schemas-upnp-org:metadata-1-0/DIDL-Lite/}item'):
                item_id = item.get('id')
                res = item.find('{urn:schemas-upnp-org:metadata-1-0/DIDL-Lite/}res')
                if res is not None:
                    uri = res.text
                    # Extract checksum from custom metadata if available
                    desc = item.find('{urn:schemas-upnp-org:metadata-1-0/DIDL-Lite/}desc')
                    checksum = desc.text if desc is not None else hashlib.md5(uri.encode()).hexdigest()
                    inventory[checksum] = item_id
        return inventory

    def upload_file(self, media_file: MediaFile) -> bool:
        """Upload file to Sonos via network share or HTTP."""
        logger.info(f"Uploading {media_file.path.name} to {self.device_id}")
        # Simulate upload via SMB or HTTP POST to device
        try:
            # In production, this would use requests to POST to the device's file endpoint
            # or copy to a network share that Sonos indexes
            return True
        except Exception as e:
            logger.error(f"Upload failed: {e}")
            return False

    def delete_file(self, remote_id: str) -> bool:
        """Remove track from Sonos queue/library."""
        logger.info(f"Deleting {remote_id} from {self.device_id}")
        return True

    def update_playlist(self, file_ids: List[str]) -> bool:
        """Update the saved queue on Sonos."""
        logger.info(f"Updating playlist on {self.device_id} with {len(file_ids)} tracks")
        return True


class AmazonEchoClient(SpeakerClient):
    """Client for Amazon Echo devices."""

    def __init__(self, config: Dict):
        super().__init__(config)
        self.api_base = f"http://{self.ip_address}:{self.api_port}/api"

    def get_remote_inventory(self) -> Dict[str, str]:
        """Get current media from Echo via local API."""
        try:
            response = self.session.get(f"{self.api_base}/media/inventory")
            data = response.json()
            return {item['checksum']: item['id'] for item in data.get('tracks', [])}
        except Exception as e:
            logger.error(f"Failed to get Echo inventory: {e}")
            return {}

    def upload_file(self, media_file: MediaFile) -> bool:
        """Upload to Echo via Bluetooth or local network share."""
        logger.info(f"Sending {media_file.path.name} to Echo {self.device_id}")
        return True

    def delete_file(self, remote_id: str) -> bool:
        logger.info(f"Removing track from Echo {self.device_id}")
        return True

    def update_playlist(self, file_ids: List[str]) -> bool:
        logger.info(f"Updating Alexa playlist for {self.device_id}")
        return True


class GoogleNestClient(SpeakerClient):
    """Client for Google Nest/Home devices."""

    def __init__(self, config: Dict):
        super().__init__(config)
        self.cast_url = f"http://{self.ip_address}:{self.api_port}/cast"

    def get_remote_inventory(self) -> Dict[str, str]:
        """Get cached media from Google Home."""
        try:
            response = self.session.get(f"{self.cast_url}/media")
            data = response.json()
            inventory = {}
            for item in data:
                # Google uses content hashes differently
                key = item.get('content_id', item.get('title', 'unknown'))
                inventory[key] = item['media_id']
            return inventory
        except Exception as e:
            logger.error(f"Google Nest API error: {e}")
            return {}

    def upload_file(self, media_file: MediaFile) -> bool:
        """Upload to Google Home via Google Cast or local CDN."""
        logger.info(f"Casting/uploading {media_file.path.name} to Nest {self.device_id}")
        return True

    def delete_file(self, remote_id: str) -> bool:
        logger.info(f"Removing from Google Home {self.device_id}")
        return True

    def update_playlist(self, file_ids: List[str]) -> bool:
        logger.info(f"Updating Google Home group playlist {self.device_id}")
        return True


class MediaLibrary:
    """Manages the local media library scanning and indexing."""

    def __init__(self, library_path: str):
        self.library_path = Path(library_path)
        self.media_files: Dict[str, MediaFile] = {}
        self.supported_formats = {'.mp3', '.flac', '.m4a', '.ogg'}

    def scan(self) -> Dict[str, MediaFile]:
        """Scan library directory for media files."""
        logger.info(f"Scanning library at {self.library_path}")
        self.media_files = {}

        if not self.library_path.exists():
            raise FileNotFoundError(f"Library path does not exist: {self.library_path}")

        for file_path in self.library_path.rglob('*'):
            if file_path.suffix.lower() in self.supported_formats:
                try:
                    stat = file_path.stat()
                    checksum = self._calculate_checksum(file_path)
                    media_file = MediaFile(
                        path=file_path,
                        checksum=checksum,
                        size=stat.st_size,
                        modified_time=datetime.fromtimestamp(stat.st_mtime, tz=timezone.utc),
                        format=file_path.suffix.lower().replace('.', '')
                    )
                    self.media_files[checksum] = media_file
                    logger.debug(f"Indexed: {file_path.name} ({checksum[:8]}...)")
                except Exception as e:
                    logger.error(f"Failed to process {file_path}: {e}")

        logger.info(f"Library scan complete: {len(self.media_files)} files found")
        return self.media_files

    def _calculate_checksum(self, file_path: Path) -> str:
        """Calculate MD5 checksum of file."""
        hash_md5 = hashlib.md5()
        with open(file_path, "rb") as f:
            for chunk in iter(lambda: f.read(4096), b""):
                hash_md5.update(chunk)
        return hash_md5.hexdigest()

    def get_file_by_checksum(self, checksum: str) -> Optional[MediaFile]:
        """Retrieve media file by checksum."""
        return self.media_files.get(checksum)


class SyncManager:
    """Orchestrates synchronization between library and speakers."""

    def __init__(self, config_path: str):
        self.config_path = Path(config_path)
        self.config = self._load_config()
        self.library = MediaLibrary(self.config['library_path'])
        self.clients = self._initialize_clients()

    def _load_config(self) -> Dict:
        """Load configuration from JSON file."""
        with open(self.config_path, 'r') as f:
            return json.load(f)

    def _save_config(self):
        """Save updated configuration back to JSON."""
        with open(self.config_path, 'w') as f:
            json.dump(self.config, f, indent=2, default=str)

    def _initialize_clients(self) -> Dict[str, SpeakerClient]:
        """Initialize API clients for each configured speaker."""
        clients = {}
        for speaker in self.config['speakers']:
            speaker_id = speaker['id']
            speaker_type = speaker['type'].lower()

            try:
                if 'sonos' in speaker_type:
                    clients[speaker_id] = SonosClient(speaker)
                elif 'echo' in speaker_type or 'amazon' in speaker_type:
                    clients[speaker_id] = AmazonEchoClient(speaker)
                elif 'nest' in speaker_type or 'google' in speaker_type:
                    clients[speaker_id] = GoogleNestClient(speaker)
                else:
                    logger.warning(f"Unknown speaker type for {speaker_id}: {speaker_type}")
            except Exception as e:
                logger.error(f"Failed to initialize client for {speaker_id}: {e}")

        return clients

    def sync_speaker(self, speaker_id: str, dry_run: bool = False) -> bool:
        """Synchronize library with a specific speaker."""
        if speaker_id not in self.clients:
            logger.error(f"No client available for speaker: {speaker_id}")
            return False

        client = self.clients[speaker_id]
        speaker_config = next(s for s in self.config['speakers'] if s['id'] == speaker_id)

        logger.info(f"Starting sync for {speaker_config['name']} ({speaker_id})")

        try:
            # Get remote inventory
            remote_inventory = client.get_remote_inventory()
            local_files = self.library.media_files

            # Determine actions needed
            to_upload = []
            to_delete = []

            # Find files to upload (new or changed)
            for checksum, media_file in local_files.items():
                if checksum not in remote_inventory:
                    if media_file.format in speaker_config['supported_formats']:
                        to_upload.append(media_file)
                    else:
                        logger.warning(f"Format {media_file.format} not supported by {speaker_id}, skipping {media_file.path.name}")

            # Find files to delete (removed from library)
            remote_checksums = set(remote_inventory.keys())
            local_checksums = set(local_files.keys())
            orphaned = remote_checksums - local_checksums

            for checksum in orphaned:
                remote_id = remote_inventory[checksum]
                to_delete.append(remote_id)

            logger.info(f"Sync plan for {speaker_id}: {len(to_upload)} uploads, {len(to_delete)} deletions")

            if dry_run:
                logger.info("Dry run mode - no changes made")
                return True

            # Execute uploads
            successful_uploads = []
            for media_file in to_upload:
                if client.upload_file(media_file):
                    successful_uploads.append(media_file.checksum)
                else:
                    logger.error(f"Failed to upload {media_file.path.name} to {speaker_id}")

            # Execute deletions
            for remote_id in to_delete:
                if not client.delete_file(remote_id):
                    logger.warning(f"Failed to delete {remote_id} from {speaker_id}")

            # Update playlist
            if successful_uploads or to_delete:
                all_ids = list(remote_inventory.values()) + [f"local_{c}" for c in successful_uploads]
                # Remove deleted IDs
                all_ids = [id for id in all_ids if id not in to_delete]
                client.update_playlist(all_ids)

            # Update config timestamp
            speaker_config['last_sync'] = datetime.now(timezone.utc).isoformat()
            speaker_config['sync_status'] = 'synced'
            if 'error_message' in speaker_config:
                del speaker_config['error_message']

            logger.info(f"Sync completed successfully for {speaker_id}")
            return True

        except Exception as e:
            logger.error(f"Sync failed for {speaker_id}: {e}")
            speaker_config['sync_status'] = 'error'
            speaker_config['error_message'] = str(e)
            return False

    def sync_all(self, dry_run: bool = False) -> Dict[str, bool]:
        """Synchronize all configured speakers."""
        results = {}
        self.library.scan()

        for speaker in self.config['speakers']:
            speaker_id = speaker['id']
            if speaker_id in self.clients:
                results[speaker_id] = self.sync_speaker(speaker_id, dry_run)
            else:
                logger.warning(f"No client for speaker {speaker_id}, skipping")
                results[speaker_id] = False

        self._save_config()
        return results


def main():
    parser = argparse.ArgumentParser(
        description='Synchronize local media library with smart speakers',
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog="""
Examples:
  %(prog)s --config media_config.json --sync-all
  %(prog)s --speaker sonos_arc_living_01 --dry-run
  %(prog)s --list-speakers
        """
    )

    parser.add_argument('--config', default='media_config.json',
                       help='Path to configuration file (default: media_config.json)')
    parser.add_argument('--sync-all', action='store_true',
                       help='Synchronize all configured speakers')
    parser.add_argument('--speaker', metavar='ID',
                       help='Synchronize specific speaker by ID')
    parser.add_argument('--dry-run', action='store_true',
                       help='Show what would be done without making changes')
    parser.add_argument('--list-speakers', action='store_true',
                       help='List all configured speakers and their status')
    parser.add_argument('--verbose', '-v', action='store_true',
                       help='Enable verbose logging')

    args = parser.parse_args()

    if args.verbose:
        logging.getLogger().setLevel(logging.DEBUG)

    if not os.path.exists(args.config):
        logger.error(f"Configuration file not found: {args.config}")
        return 1

    try:
        manager = SyncManager(args.config)

        if args.list_speakers:
            print(f"{'ID':<30} {'Name':<25} {'Room':<15} {'Status':<12} {'Last Sync'}")
            print("-" * 100)
            for speaker in manager.config['speakers']:
                last_sync = speaker.get('last_sync', 'Never')[:19] if speaker.get('last_sync') else 'Never'
                print(f"{speaker['id']:<30} {speaker['name']:<25} {speaker['room']:<15} "
                      f"{speaker['sync_status']:<12} {last_sync}")
            return 0

        if args.speaker:
            manager.library.scan()
            success = manager.sync_speaker(args.speaker, args.dry_run)
            manager._save_config()
            return 0 if success else 1

        if args.sync_all:
            results = manager.sync_all(args.dry_run)
            success_count = sum(1 for v in results.values() if v)
            total = len(results)
            logger.info(f"Sync complete: {success_count}/{total} speakers synchronized")
            return 0 if success_count == total else 1

        parser.print_help()
        return 0

    except Exception as e:
        logger.exception("Fatal error during execution")
        return 1


if __name__ == '__main__':
    exit(main())

