// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title LiquidityPoolV2
 * @notice A constant product automated market maker (AMM) liquidity pool
 * @dev Implements Uniswap V2 style logic with customizable fees
 */
contract LiquidityPoolV2 is ReentrancyGuard, Ownable {
    IERC20 public immutable token0;
    IERC20 public immutable token1;

    uint256 public reserve0;
    uint256 public reserve1;
    uint256 public totalSupply;

    mapping(address => uint256) public balanceOf;

    uint256 public constant MINIMUM_LIQUIDITY = 10**3;
    uint256 public fee = 3; // 0.3% = 3/1000

    event Mint(address indexed sender, uint256 amount0, uint256 amount1);
    event Burn(address indexed sender, uint256 amount0, uint256 amount1, address indexed to);
    event Swap(
        address indexed sender, 
        uint256 amountIn, 
        uint256 amountOut, 
        address indexed tokenIn, 
        address indexed tokenOut
    );
    event Sync(uint256 reserve0, uint256 reserve1);
    event FeeUpdated(uint256 newFee);

    constructor(address _token0, address _token1) {
        require(_token0 != address(0) && _token1 != address(0), "LP: ZERO_ADDRESS");
        require(_token0 != _token1, "LP: IDENTICAL_ADDRESSES");
        token0 = IERC20(_token0);
        token1 = IERC20(_token1);
    }

    /**
     * @notice Add liquidity to the pool
     * @param amount0Desired Desired amount of token0 to add
     * @param amount1Desired Desired amount of token1 to add
     * @param amount0Min Minimum amount of token0 to add (slippage protection)
     * @param amount1Min Minimum amount of token1 to add (slippage protection)
     * @return liquidity Amount of LP tokens minted
     */
    function addLiquidity(
        uint256 amount0Desired, 
        uint256 amount1Desired, 
        uint256 amount0Min, 
        uint256 amount1Min
    ) 
        external 
        nonReentrant 
        returns (uint256 liquidity) 
    {
        (uint256 amount0, uint256 amount1) = _calculateLiquidityAmounts(
            amount0Desired, 
            amount1Desired, 
            amount0Min, 
            amount1Min
        );

        token0.transferFrom(msg.sender, address(this), amount0);
        token1.transferFrom(msg.sender, address(this), amount1);

        uint256 _totalSupply = totalSupply;
        if (_totalSupply == 0) {
            liquidity = sqrt(amount0 * amount1) - MINIMUM_LIQUIDITY;
            _mint(address(0), MINIMUM_LIQUIDITY); // Lock minimum liquidity forever
        } else {
            liquidity = min(
                (amount0 * _totalSupply) / reserve0, 
                (amount1 * _totalSupply) / reserve1
            );
        }

        require(liquidity > 0, "LP: INSUFFICIENT_LIQUIDITY_MINTED");
        _mint(msg.sender, liquidity);

        _updateReserves();
        emit Mint(msg.sender, amount0, amount1);
    }

    /**
     * @notice Remove liquidity from the pool
     * @param liquidity Amount of LP tokens to burn
     * @param amount0Min Minimum amount of token0 to receive
     * @param amount1Min Minimum amount of token1 to receive
     * @param to Address to receive the tokens
     * @return amount0 Actual amount of token0 received
     * @return amount1 Actual amount of token1 received
     */
    function removeLiquidity(
        uint256 liquidity, 
        uint256 amount0Min, 
        uint256 amount1Min, 
        address to
    ) 
        external 
        nonReentrant 
        returns (uint256 amount0, uint256 amount1) 
    {
        uint256 _totalSupply = totalSupply;
        amount0 = (liquidity * reserve0) / _totalSupply;
        amount1 = (liquidity * reserve1) / _totalSupply;

        require(amount0 >= amount0Min, "LP: INSUFFICIENT_0_AMOUNT");
        require(amount1 >= amount1Min, "LP: INSUFFICIENT_1_AMOUNT");

        _burn(msg.sender, liquidity);

        token0.transfer(to, amount0);
        token1.transfer(to, amount1);

        _updateReserves();
        emit Burn(msg.sender, amount0, amount1, to);
    }

    /**
     * @notice Swap tokens
     * @param amountIn Amount of input tokens
     * @param tokenIn Address of input token (must be token0 or token1)
     * @param amountOutMin Minimum amount of output tokens
     * @return amountOut Actual amount of output tokens
     */
    function swap(
        uint256 amountIn, 
        address tokenIn, 
        uint256 amountOutMin
    ) 
        external 
        nonReentrant 
        returns (uint256 amountOut) 
    {
        require(tokenIn == address(token0) || tokenIn == address(token1), "LP: INVALID_TOKEN");
        require(amountIn > 0, "LP: ZERO_AMOUNT");

        bool isToken0 = tokenIn == address(token0);
        (IERC20 inputToken, IERC20 outputToken, uint256 inputReserve, uint256 outputReserve) = isToken0 
            ? (token0, token1, reserve0, reserve1) 
            : (token1, token0, reserve1, reserve0);

        inputToken.transferFrom(msg.sender, address(this), amountIn);

        uint256 amountInWithFee = (amountIn * (1000 - fee)) / 1000;
        amountOut = (amountInWithFee * outputReserve) / (inputReserve + amountInWithFee);

        require(amountOut >= amountOutMin, "LP: INSUFFICIENT_OUTPUT_AMOUNT");
        require(amountOut < outputReserve, "LP: INSUFFICIENT_LIQUIDITY");

        outputToken.transfer(msg.sender, amountOut);

        _updateReserves();
        emit Swap(msg.sender, amountIn, amountOut, tokenIn, address(outputToken));
    }

    /**
     * @notice Update fee percentage (only owner)
     * @param _fee New fee in basis points (e.g., 3 = 0.3%)
     */
    function setFee(uint256 _fee) external onlyOwner {
        require(_fee <= 100, "LP: FEE_TOO_HIGH"); // Max 10%
        fee = _fee;
        emit FeeUpdated(_fee);
    }

    /**
     * @notice Sync reserves with current balances (emergency use)
     */
    function sync() external nonReentrant {
        _updateReserves();
    }

    function _calculateLiquidityAmounts(
        uint256 amount0Desired, 
        uint256 amount1Desired, 
        uint256 amount0Min, 
        uint256 amount1Min
    ) 
        internal 
        view 
        returns (uint256 amount0, uint256 amount1) 
    {
        if (reserve0 == 0 && reserve1 == 0) {
            (amount0, amount1) = (amount0Desired, amount1Desired);
        } else {
            uint256 amount1Optimal = (amount0Desired * reserve1) / reserve0;
            if (amount1Optimal <= amount1Desired) {
                require(amount1Optimal >= amount1Min, "LP: INSUFFICIENT_1_AMOUNT");
                (amount0, amount1) = (amount0Desired, amount1Optimal);
            } else {
                uint256 amount0Optimal = (amount1Desired * reserve0) / reserve1;
                require(amount0Optimal <= amount0Desired, "LP: OPTIMAL_0_TOO_HIGH");
                require(amount0Optimal >= amount0Min, "LP: INSUFFICIENT_0_AMOUNT");
                (amount0, amount1) = (amount0Optimal, amount1Desired);
            }
        }
    }

    function _updateReserves() internal {
        reserve0 = token0.balanceOf(address(this));
        reserve1 = token1.balanceOf(address(this));
        emit Sync(reserve0, reserve1);
    }

    function _mint(address to, uint256 value) internal {
        totalSupply += value;
        balanceOf[to] += value;
    }

    function _burn(address from, uint256 value) internal {
        balanceOf[from] -= value;
        totalSupply -= value;
    }

    function sqrt(uint256 y) internal pure returns (uint256 z) {
        if (y > 3) {
            z = y;
            uint256 x = y / 2 + 1;
            while (x < z) {
                z = x;
                x = (y / x + x) / 2;
            }
        } else if (y != 0) {
            z = 1;
        }
    }

    function min(uint256 x, uint256 y) internal pure returns (uint256) {
        return x < y ? x : y;
    }
}

