// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC4626.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";

/**
 * @title Vault
 * @notice ERC4626-compliant yield vault with role-based access control and security features
 * @dev Part of SecureYield Protocol v2.1.0 - Prepared for security audit baseline
 * @custom:security-contact security@secureyield.io
 */
contract Vault is ERC4626, ReentrancyGuard, Pausable, AccessControl {
    using SafeERC20 for IERC20;

    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");
    bytes32 public constant HARVESTER_ROLE = keccak256("HARVESTER_ROLE");
    bytes32 public constant FEE_MANAGER_ROLE = keccak256("FEE_MANAGER_ROLE");
    bytes32 public constant ASSET_MANAGER_ROLE = keccak256("ASSET_MANAGER_ROLE");

    uint256 public constant MAX_BPS = 10_000;
    uint256 public constant MIN_DEPOSIT_COOLDOWN = 1 days;

    uint256 public managementFee; // Basis points (e.g., 100 = 1%)
    uint256 public performanceFee; // Basis points
    uint256 public totalAssetsLocked;
    address public feeRecipient;
    address public governance;

    mapping(address => uint256) public lastDepositTime;
    mapping(address => bool) public whitelistedStrategies;

    event Harvested(uint256 grossAmount, uint256 netAmount, uint256 fee, uint256 timestamp);
    event FeesUpdated(uint256 oldManagementFee, uint256 newManagementFee, uint256 oldPerformanceFee, uint256 newPerformanceFee);
    event FeeRecipientUpdated(address oldRecipient, address newRecipient);
    event EmergencyShutdown(bool paused, uint256 timestamp);
    event StrategyWhitelisted(address strategy, bool status);

    error ZeroAmount();
    error ZeroAddress();
    error FeeTooHigh();
    error CooldownPeriodActive();
    error InsufficientAssets();
    error UnauthorizedStrategy();
    error TransferFailed();

    modifier nonZeroAmount(uint256 amount) {
        if (amount == 0) revert ZeroAmount();
        _;
    }

    modifier onlyGovernance() {
        require(msg.sender == governance, "Vault: caller is not governance");
        _;
    }

    constructor(
        IERC20 asset_,
        string memory name_,
        string memory symbol_,
        address admin,
        address governance_,
        address feeRecipient_,
        uint256 managementFee_,
        uint256 performanceFee_
    ) ERC4626(asset_) ERC20(name_, symbol_) {
        if (admin == address(0) || feeRecipient_ == address(0) || governance_ == address(0)) {
            revert ZeroAddress();
        }
        if (managementFee_ > 500 || performanceFee_ > 2000) revert FeeTooHigh();

        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(PAUSER_ROLE, admin);
        _grantRole(HARVESTER_ROLE, admin);
        _grantRole(FEE_MANAGER_ROLE, admin);
        _grantRole(ASSET_MANAGER_ROLE, admin);

        governance = governance_;
        feeRecipient = feeRecipient_;
        managementFee = managementFee_;
        performanceFee = performanceFee_;
    }

    /**
     * @notice Deposits assets and mints shares to receiver
     * @param assets Amount of assets to deposit
     * @param receiver Address to receive the shares
     * @return shares Amount of shares minted
     */
    function deposit(uint256 assets, address receiver) 
        public 
        virtual 
        override 
        nonReentrant 
        whenNotPaused 
        nonZeroAmount(assets) 
        returns (uint256 shares) 
    {
        lastDepositTime[receiver] = block.timestamp;
        shares = super.deposit(assets, receiver);
        totalAssetsLocked += assets;
    }

    /**
     * @notice Mints exact shares to receiver by depositing proportional assets
     */
    function mint(uint256 shares, address receiver) 
        public 
        virtual 
        override 
        nonReentrant 
        whenNotPaused 
        nonZeroAmount(shares) 
        returns (uint256 assets) 
    {
        lastDepositTime[receiver] = block.timestamp;
        assets = super.mint(shares, receiver);
        totalAssetsLocked += assets;
    }

    /**
     * @notice Withdraws exact assets to receiver, burning shares from owner
     */
    function withdraw(uint256 assets, address receiver, address owner) 
        public 
        virtual 
        override 
        nonReentrant 
        nonZeroAmount(assets) 
        returns (uint256 shares) 
    {
        if (block.timestamp < lastDepositTime[owner] + MIN_DEPOSIT_COOLDOWN) {
            revert CooldownPeriodActive();
        }
        shares = super.withdraw(assets, receiver, owner);
        totalAssetsLocked -= assets;
    }

    /**
     * @notice Redeems exact shares for assets
     */
    function redeem(uint256 shares, address receiver, address owner) 
        public 
        virtual 
        override 
        nonReentrant 
        nonZeroAmount(shares) 
        returns (uint256 assets) 
    {
        if (block.timestamp < lastDepositTime[owner] + MIN_DEPOSIT_COOLDOWN) {
            revert CooldownPeriodActive();
        }
        assets = super.redeem(shares, receiver, owner);
        totalAssetsLocked -= assets;
    }

    /**
     * @notice Harvests yield from strategies and distributes fees
     * @param amount Gross amount harvested
     * @param strategy Address of strategy to harvest from (must be whitelisted)
     */
    function harvest(uint256 amount, address strategy) 
        external 
        onlyRole(HARVESTER_ROLE) 
        nonReentrant 
    {
        if (amount == 0) revert ZeroAmount();
        if (!whitelistedStrategies[strategy]) revert UnauthorizedStrategy();

        uint256 performanceFeeAmount = (amount * performanceFee) / MAX_BPS;
        uint256 netAmount = amount - performanceFeeAmount;

        if (performanceFeeAmount > 0) {
            IERC20(asset()).safeTransfer(feeRecipient, performanceFeeAmount);
        }

        // Reinvest netAmount or add to totalAssetsLocked
        totalAssetsLocked += netAmount;

        emit Harvested(amount, netAmount, performanceFeeAmount, block.timestamp);
    }

    /**
     * @notice Updates fee structure (subject to timelock via governance)
     */
    function setFees(uint256 newManagementFee, uint256 newPerformanceFee) 
        external 
        onlyRole(FEE_MANAGER_ROLE) 
    {
        if (newManagementFee > 500 || newPerformanceFee > 2000) revert FeeTooHigh();

        uint256 oldMgmt = managementFee;
        uint256 oldPerf = performanceFee;

        managementFee = newManagementFee;
        performanceFee = newPerformanceFee;

        emit FeesUpdated(oldMgmt, newManagementFee, oldPerf, newPerformanceFee);
    }

    /**
     * @notice Updates fee recipient address
     */
    function setFeeRecipient(address newRecipient) 
        external 
        onlyRole(FEE_MANAGER_ROLE) 
    {
        if (newRecipient == address(0)) revert ZeroAddress();
        address oldRecipient = feeRecipient;
        feeRecipient = newRecipient;
        emit FeeRecipientUpdated(oldRecipient, newRecipient);
    }

    /**
     * @notice Whitelist or unwhitelist a strategy for harvesting
     */
    function setStrategyWhitelist(address strategy, bool status) 
        external 
        onlyRole(ASSET_MANAGER_ROLE) 
    {
        if (strategy == address(0)) revert ZeroAddress();
        whitelistedStrategies[strategy] = status;
        emit StrategyWhitelisted(strategy, status);
    }

    /**
     * @notice Emergency pause - prevents deposits and withdrawals
     */
    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
        emit EmergencyShutdown(true, block.timestamp);
    }

    /**
     * @notice Unpause - resumes normal operations
     */
    function unpause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _unpause();
        emit EmergencyShutdown(false, block.timestamp);
    }

    /**
     * @notice Returns total assets managed by vault
     */
    function totalAssets() public view virtual override returns (uint256) {
        return totalAssetsLocked;
    }

    /**
     * @dev Override to use SafeERC20 for transfers
     */
    function _deposit(address caller, address receiver, uint256 assets, uint256 shares) internal virtual override {
        IERC20(asset()).safeTransferFrom(caller, address(this), assets);
        _mint(receiver, shares);
        emit Deposit(caller, receiver, assets, shares);
    }

    /**
     * @dev Override to use SafeERC20 for transfers
     */
    function _withdraw(address caller, address receiver, address owner, uint256 assets, uint256 shares) internal virtual override {
        if (caller != owner) {
            _spendAllowance(owner, caller, shares);
        }
        _burn(owner, shares);
        IERC20(asset()).safeTransfer(receiver, assets);
        emit Withdraw(caller, receiver, owner, assets, shares);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/Address.sol";

/**
 * @title Governance
 * @notice Central governance and timelock controller for SecureYield Protocol
 * @dev Manages protocol parameters, emergency functions, and role administration
 * @custom:security-contact security@secureyield.io
 */
contract Governance is AccessControl, Pausable {
    using Address for address;

    bytes32 public constant PROPOSER_ROLE = keccak256("PROPOSER_ROLE");
    bytes32 public constant EXECUTOR_ROLE = keccak256("EXECUTOR_ROLE");
    bytes32 public constant CANCELLER_ROLE = keccak256("CANCELLER_ROLE");
    bytes32 public constant EMERGENCY_ROLE = keccak256("EMERGENCY_ROLE");
    bytes32 public constant PARAMETER_ADMIN_ROLE = keccak256("PARAMETER_ADMIN_ROLE");

    uint256 public minDelay;
    uint256 public constant GRACE_PERIOD = 14 days;
    uint256 public constant MINIMUM_DELAY = 1 days;
    uint256 public constant MAXIMUM_DELAY = 30 days;

    mapping(bytes32 => Proposal) public proposals;
    mapping(address => bool) public authorizedContracts;

    struct Proposal {
        address target;
        uint256 value;
        bytes data;
        uint256 eta;
        bool executed;
        bool cancelled;
    }

    event ProposalQueued(
        bytes32 indexed proposalId,
        address indexed target,
        uint256 value,
        bytes data,
        uint256 eta
    );
    event ProposalExecuted(bytes32 indexed proposalId, address indexed target);
    event ProposalCancelled(bytes32 indexed proposalId);
    event MinDelayUpdated(uint256 oldDuration, uint256 newDuration);
    event ContractAuthorizationChanged(address indexed contractAddress, bool authorized);
    event EmergencyActionExecuted(address indexed target, bytes data);

    error InvalidDelay();
    error InvalidTarget();
    error InvalidProposalId();
    error ProposalNotQueued();
    error ProposalAlreadyExecuted();
    error ProposalAlreadyCancelled();
    error ProposalNotReady();
    error ProposalExpired();
    error TransactionFailed();
    error UnauthorizedContract();
    error InsufficientValue();

    modifier onlyAuthorizedContract(address target) {
        if (!authorizedContracts[target]) revert UnauthorizedContract();
        _;
    }

    constructor(
        uint256 minDelay_,
        address admin,
        address[] memory proposers,
        address[] memory executors,
        address[] memory cancellers
    ) {
        if (minDelay_ < MINIMUM_DELAY || minDelay_ > MAXIMUM_DELAY) {
            revert InvalidDelay();
        }

        minDelay = minDelay_;

        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(EMERGENCY_ROLE, admin);
        _grantRole(PARAMETER_ADMIN_ROLE, admin);
        _setRoleAdmin(PROPOSER_ROLE, DEFAULT_ADMIN_ROLE);
        _setRoleAdmin(EXECUTOR_ROLE, DEFAULT_ADMIN_ROLE);
        _setRoleAdmin(CANCELLER_ROLE, DEFAULT_ADMIN_ROLE);

        for (uint256 i = 0; i < proposers.length; i++) {
            _grantRole(PROPOSER_ROLE, proposers[i]);
        }

        for (uint256 i = 0; i < executors.length; i++) {
            _grantRole(EXECUTOR_ROLE, executors[i]);
        }

        for (uint256 i = 0; i < cancellers.length; i++) {
            _grantRole(CANCELLER_ROLE, cancellers[i]);
        }
    }

    /**
     * @notice Queue a proposal for execution after timelock
     */
    function queueTransaction(
        address target,
        uint256 value,
        bytes calldata data,
        uint256 eta
    ) external onlyRole(PROPOSER_ROLE) returns (bytes32 proposalId) {
        if (target == address(0)) revert InvalidTarget();
        if (eta < block.timestamp + minDelay) revert InvalidDelay();
        if (eta > block.timestamp + MAXIMUM_DELAY) revert InvalidDelay();

        proposalId = keccak256(abi.encode(target, value, data, eta));

        if (proposals[proposalId].eta != 0) revert InvalidProposalId();

        proposals[proposalId] = Proposal({
            target: target,
            value: value,
            data: data,
            eta: eta,
            executed: false,
            cancelled: false
        });

        emit ProposalQueued(proposalId, target, value, data, eta);
    }

    /**
     * @notice Execute a queued proposal after timelock expires
     */
    function executeTransaction(bytes32 proposalId) external payable onlyRole(EXECUTOR_ROLE) {
        Proposal storage proposal = proposals[proposalId];

        if (proposal.eta == 0) revert ProposalNotQueued();
        if (proposal.executed) revert ProposalAlreadyExecuted();
        if (proposal.cancelled) revert ProposalAlreadyCancelled();
        if (block.timestamp < proposal.eta) revert ProposalNotReady();
        if (block.timestamp > proposal.eta + GRACE_PERIOD) revert ProposalExpired();
        if (msg.value < proposal.value) revert InsufficientValue();

        proposal.executed = true;

        (bool success, ) = proposal.target.call{value: proposal.value}(proposal.data);
        if (!success) revert TransactionFailed();

        emit ProposalExecuted(proposalId, proposal.target);
    }

    /**
     * @notice Cancel a queued proposal
     */
    function cancelTransaction(bytes32 proposalId) external onlyRole(CANCELLER_ROLE) {
        Proposal storage proposal = proposals[proposalId];

        if (proposal.eta == 0) revert ProposalNotQueued();
        if (proposal.executed) revert ProposalAlreadyExecuted();
        if (proposal.cancelled) revert ProposalAlreadyCancelled();

        proposal.cancelled = true;

        emit ProposalCancelled(proposalId);
    }

    /**
     * @notice Update minimum delay for proposals
     */
    function setMinDelay(uint256 newDelay) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (newDelay < MINIMUM_DELAY || newDelay > MAXIMUM_DELAY) revert InvalidDelay();

        uint256 oldDelay = minDelay;
        minDelay = newDelay;

        emit MinDelayUpdated(oldDelay, newDelay);
    }

    /**
     * @notice Authorize or deauthorize a contract for governance control
     */
    function setContractAuthorization(address contractAddress, bool authorized) 
        external 
        onlyRole(PARAMETER_ADMIN_ROLE) 
    {
        if (contractAddress == address(0)) revert InvalidTarget();
        authorizedContracts[contractAddress] = authorized;
        emit ContractAuthorizationChanged(contractAddress, authorized);
    }

    /**
     * @notice Emergency pause for authorized contracts
     */
    function emergencyPause(address target) 
        external 
        onlyRole(EMERGENCY_ROLE) 
        onlyAuthorizedContract(target) 
    {
        Pausable(target).pause();
    }

    /**
     * @notice Emergency unpause for authorized contracts
     */
    function emergencyUnpause(address target) 
        external 
        onlyRole(DEFAULT_ADMIN_ROLE) 
        onlyAuthorizedContract(target) 
    {
        Pausable(target).unpause();
    }

    /**
     * @notice Execute arbitrary call in emergency (requires both EMERGENCY_ROLE and high threshold)
     * @dev This is a dangerous function and should be used only in extreme emergencies
     */
    function emergencyExecute(
        address target,
        bytes calldata data
    ) external payable onlyRole(EMERGENCY_ROLE) onlyAuthorizedContract(target) {
        (bool success, ) = target.call{value: msg.value}(data);
        if (!success) revert TransactionFailed();

        emit EmergencyActionExecuted(target, data);
    }

    /**
     * @notice Grant role with additional authorization check
     */
    function grantRole(bytes32 role, address account) 
        public 
        override 
        onlyRole(getRoleAdmin(role)) 
    {
        super.grantRole(role, account);
    }

    /**
     * @notice Revoke role with additional authorization check
     */
    function revokeRole(bytes32 role, address account) 
        public 
        override 
        onlyRole(getRoleAdmin(role)) 
    {
        super.revokeRole(role, account);
    }

    /**
     * @notice Renounce role for self
     */
    function renounceRole(bytes32 role, address account) 
        public 
        override 
    {
        super.renounceRole(role, account);
    }

    receive() external payable {}
}

