#!/usr/bin/env python3
"""
share_referral.py

Clinical Referral Transmission Utility
University Medical Center - External Collaboration Module

Packages clinical notes and transmits to external healthcare providers
via secure FHIR R4 API endpoints.

Usage:
    python share_referral.py --input patient_cardio_notes.txt --provider metro_heart
    python share_referral.py --input notes.txt --provider metro_heart --dry-run
"""

import argparse
import json
import logging
import os
import re
import sys
from datetime import datetime
from pathlib import Path
from typing import Dict, Optional

import requests
from requests.adapters import HTTPAdapter
from urllib3.util.retry import Retry

# Configuration
CONFIG = {
    "metro_heart": {
        "name": "Metro Heart Institute",
        "endpoint": "https://api.metroheart.org/v2/referrals",
        "api_key_env": "METRO_HEART_API_KEY",
        "timeout": 30,
        "headers": {
            "Content-Type": "application/fhir+json",
            "Accept": "application/fhir+json"
        }
    },
    "regional_cardiac": {
        "name": "Regional Cardiac Center",
        "endpoint": "https://api.regionalcardiac.com/fhir/R4/Referral",
        "api_key_env": "REGIONAL_CARDIAC_API_KEY",
        "timeout": 45,
        "headers": {
            "Content-Type": "application/fhir+json"
        }
    }
}

# Setup logging
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s [%(levelname)s] [%(session_id)s] %(message)s',
    handlers=[
        logging.FileHandler('referral_logs.log'),
        logging.StreamHandler(sys.stdout)
    ]
)
logger = logging.getLogger(__name__)


class ReferralClient:
    """Client for transmitting clinical referrals to external providers."""

    def __init__(self, provider_key: str, session_id: Optional[str] = None):
        self.provider_key = provider_key
        self.config = CONFIG.get(provider_key)
        if not self.config:
            raise ValueError(f"Unknown provider: {provider_key}")

        self.session_id = session_id or datetime.now().strftime("%Y%m%d%H%M%S")
        self.api_key = os.getenv(self.config["api_key_env"])
        if not self.api_key:
            raise EnvironmentError(f"Missing API key: {self.config['api_key_env']}")

        self.session = requests.Session()
        retry_strategy = Retry(
            total=3,
            backoff_factor=1,
            status_forcelist=[429, 500, 502, 503, 504],
        )
        adapter = HTTPAdapter(max_retries=retry_strategy)
        self.session.mount("http://", adapter)
        self.session.mount("https://", adapter)

        # Add auth header
        self.config["headers"]["Authorization"] = f"Bearer {self.api_key}"

        # Extra logging context
        self.extra = {'session_id': self.session_id}

    def parse_clinical_notes(self, file_path: str) -> Dict:
        """Parse structured clinical notes into a dictionary."""
        logger.info(f"Parsing clinical notes: {file_path}", extra=self.extra)

        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                content = f.read()
        except FileNotFoundError:
            logger.error(f"File not found: {file_path}", extra=self.extra)
            raise

        # Extract key fields using regex patterns
        data = {
            'raw_content': content,
            'mrn': self._extract_pattern(content, r'MRN:\s*(\d{3}-\d{2}-\d{3})'),
            'patient_name': self._extract_pattern(content, r'Patient Name:\s*([^\n]+)'),
            'dob': self._extract_pattern(content, r'DOB:\s*(\d{2}/\d{2}/\d{4})'),
            'referring_physician': self._extract_pattern(content, r'Referring Physician:\s*([^\n]+)'),
            'date_of_visit': self._extract_pattern(content, r'Date of Visit:\s*([^\n]+)'),
            'urgency': self._extract_pattern(content, r'URGENCY:\s*([^\n]+)'),
            'assessment': self._extract_section(content, 'ASSESSMENT:', 'PLAN'),
            'plan': self._extract_section(content, 'PLAN/RECOMMENDATIONS:', 'REFERRED TO'),
            'destination_provider': self._extract_pattern(content, r'REFERRED TO:\s*([^\n]+)')
        }

        # Validate required fields
        if not data['mrn']:
            raise ValueError("MRN not found in clinical notes")

        logger.info(f"Successfully parsed MRN: {data['mrn']}", extra=self.extra)
        return data

    def _extract_pattern(self, text: str, pattern: str) -> Optional[str]:
        """Extract text using regex pattern."""
        match = re.search(pattern, text, re.IGNORECASE)
        return match.group(1).strip() if match else None

    def _extract_section(self, text: str, start_marker: str, end_marker: str) -> str:
        """Extract text between two markers."""
        pattern = f"{start_marker}(.*?)(?={end_marker}|---|$)"
        match = re.search(pattern, text, re.DOTALL | re.IGNORECASE)
        return match.group(1).strip() if match else ""

    def construct_fhir_bundle(self, data: Dict) -> Dict:
        """Construct FHIR R4 Bundle for referral transmission."""
        timestamp = datetime.now().isoformat()

        bundle = {
            "resourceType": "Bundle",
            "id": f"referral-{self.session_id}",
            "meta": {
                "versionId": "1",
                "lastUpdated": timestamp
            },
            "type": "message",
            "timestamp": timestamp,
            "entry": [
                {
                    "fullUrl": f"urn:uuid:message-header-{self.session_id}",
                    "resource": {
                        "resourceType": "MessageHeader",
                        "id": f"message-header-{self.session_id}",
                        "eventCoding": {
                            "system": "http://terminology.hl7.org/CodeSystem/message-events",
                            "code": "referral"
                        },
                        "source": {
                            "name": "University Medical Center",
                            "endpoint": "https://umc.edu/fhir"
                        },
                        "focus": [{"reference": f"ServiceRequest/{self.session_id}"}]
                    }
                },
                {
                    "fullUrl": f"urn:uuid:patient-{data['mrn']}",
                    "resource": {
                        "resourceType": "Patient",
                        "identifier": [{
                            "system": "http://umc.edu/mrn",
                            "value": data['mrn']
                        }],
                        "name": [{"text": data.get('patient_name', 'Unknown')}],
                        "birthDate": self._convert_date(data.get('dob')) if data.get('dob') else None
                    }
                },
                {
                    "fullUrl": f"urn:uuid:service-request-{self.session_id}",
                    "resource": {
                        "resourceType": "ServiceRequest",
                        "id": f"service-request-{self.session_id}",
                        "status": "active",
                        "intent": "order",
                        "priority": self._map_urgency(data.get('urgency', '')),
                        "subject": {"reference": f"urn:uuid:patient-{data['mrn']}"},
                        "requester": {
                            "display": data.get('referring_physician', 'Unknown')
                        },
                        "reasonCode": [{"text": data.get('assessment', '')}],
                        "note": [{"text": data.get('plan', '')}]
                    }
                },
                {
                    "fullUrl": f"urn:uuid:document-{self.session_id}",
                    "resource": {
                        "resourceType": "DocumentReference",
                        "id": f"document-{self.session_id}",
                        "status": "current",
                        "docStatus": "final",
                        "type": {
                            "coding": [{
                                "system": "http://loinc.org",
                                "code": "57133-1",
                                "display": "Referral note"
                            }]
                        },
                        "content": [{
                            "attachment": {
                                "contentType": "text/plain",
                                "data": data['raw_content'].encode('utf-8').hex()
                            }
                        }]
                    }
                }
            ]
        }

        return bundle

    def _convert_date(self, date_str: str) -> str:
        """Convert MM/DD/YYYY to FHIR date format."""
        try:
            dt = datetime.strptime(date_str, "%m/%d/%Y")
            return dt.strftime("%Y-%m-%d")
        except ValueError:
            return date_str

    def _map_urgency(self, urgency_text: str) -> str:
        """Map text urgency to FHIR priority codes."""
        urgency_lower = urgency_text.lower()
        if 'urgent' in urgency_lower or 'emergent' in urgency_lower:
            return "urgent"
        elif 'routine' in urgency_lower:
            return "routine"
        else:
            return "asap"

    def send_referral(self, bundle: Dict, dry_run: bool = False) -> Dict:
        """Transmit referral bundle to external provider."""
        endpoint = self.config["endpoint"]
        headers = self.config["headers"]

        payload = json.dumps(bundle, indent=2)

        logger.info(f"Preparing transmission to {self.config['name']}", extra=self.extra)
        logger.info(f"Bundle size: {len(payload)} bytes", extra=self.extra)
        logger.info(f"Endpoint: {endpoint}", extra=self.extra)

        if dry_run:
            logger.info("DRY RUN MODE - No actual transmission", extra=self.extra)
            return {
                "status": "dry_run",
                "endpoint": endpoint,
                "bundle_id": bundle["id"],
                "timestamp": datetime.now().isoformat()
            }

        try:
            response = self.session.post(
                endpoint,
                headers=headers,
                data=payload,
                timeout=self.config["timeout"]
            )
            response.raise_for_status()

            result = {
                "status": "success",
                "http_status": response.status_code,
                "response_id": response.headers.get('X-Request-ID', 'unknown'),
                "timestamp": datetime.now().isoformat(),
                "provider": self.config["name"]
            }

            logger.info(f"Transmission successful: HTTP {response.status_code}", extra=self.extra)
            logger.info(f"External Reference ID: {result['response_id']}", extra=self.extra)

            return result

        except requests.exceptions.RequestException as e:
            logger.error(f"Transmission failed: {str(e)}", extra=self.extra)
            raise


def main():
    parser = argparse.ArgumentParser(
        description="Transmit clinical referrals to external providers"
    )
    parser.add_argument(
        "--input", "-i",
        required=True,
        help="Path to clinical notes file"
    )
    parser.add_argument(
        "--provider", "-p",
        required=True,
        choices=list(CONFIG.keys()),
        help="Target provider configuration"
    )
    parser.add_argument(
        "--dry-run", "-d",
        action="store_true",
        help="Validate and construct bundle without transmitting"
    )
    parser.add_argument(
        "--session-id", "-s",
        help="Custom session ID for logging"
    )

    args = parser.parse_args()

    try:
        client = ReferralClient(args.provider, session_id=args.session_id)
        clinical_data = client.parse_clinical_notes(args.input)
        fhir_bundle = client.construct_fhir_bundle(clinical_data)
        result = client.send_referral(fhir_bundle, dry_run=args.dry_run)

        print(json.dumps(result, indent=2))
        sys.exit(0)

    except Exception as e:
        logger.error(f"Fatal error: {str(e)}")
        sys.exit(1)


if __name__ == "__main__":
    main()

